import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
/**
 * Lists the OAuth clients the current user has granted access to, with a
 * button to revoke each grant.
 */
export default class ConnectedApplications extends Component {
  consents = null;
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('oauth-consents').then(consents => this.consents = consents).catch(() => this.consents = []).finally(() => m.redraw());
  }
  view() {
    if (this.consents === null) return m(LoadingIndicator, {
      display: "block"
    });
    if (this.consents.length === 0) {
      return m("p", {
        className: "helpText"
      }, app.translator.trans('flarum-oauth-provider.forum.connected_apps.empty'));
    }
    return m("ul", {
      className: "ConnectedApplications"
    }, this.consents.map(consent => this.item(consent)));
  }
  item(consent) {
    const host = consent.clientSourceHost();
    const lastUsed = consent.lastUsedAt();
    return m("li", {
      key: consent.id(),
      className: "ConnectedApplications-item"
    }, consent.clientLogoUrl() ? m("img", {
      className: "ConnectedApplications-logo",
      src: consent.clientLogoUrl(),
      alt: ""
    }) : null, m("div", {
      className: "ConnectedApplications-info"
    }, m("strong", {
      className: "ConnectedApplications-name"
    }, consent.clientName()), host ? m("span", {
      className: "ConnectedApplications-host"
    }, app.translator.trans('flarum-oauth-provider.forum.connected_apps.from_host', {
      host
    })) : null, m("div", {
      className: "ConnectedApplications-scopes"
    }, (consent.scopes() || []).map(scope => m("code", null, scope))), m("div", {
      className: "ConnectedApplications-meta helpText"
    }, app.translator.trans('flarum-oauth-provider.forum.connected_apps.granted', {
      ago: humanTime(consent.createdAt())
    }), ' · ', lastUsed ? app.translator.trans('flarum-oauth-provider.forum.connected_apps.last_used', {
      ago: humanTime(lastUsed)
    }) : app.translator.trans('flarum-oauth-provider.forum.connected_apps.never_used'))), m(Button, {
      className: "Button Button--danger",
      onclick: () => this.revoke(consent)
    }, app.translator.trans('flarum-oauth-provider.forum.connected_apps.revoke_button')));
  }
  revoke(consent) {
    const message = extractText(app.translator.trans('flarum-oauth-provider.forum.connected_apps.revoke_confirm', {
      client: consent.clientName()
    }));
    if (!confirm(message)) return;
    consent.delete().then(() => {
      this.consents = (this.consents || []).filter(other => other !== consent);
      m.redraw();
    });
  }
}
flarum.reg.add('flarum-oauth-provider', 'forum/components/ConnectedApplications', ConnectedApplications);